<script setup>
import {nextTick,onMounted,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from '../api'
import {useUiStore} from '../stores/ui'
import {agentLine,agentStatus,assistantPayload} from '../utils/agentDisplay'
import {typeName,statusName,errorMessage} from '../utils/labels'
import {assistantResult} from '../utils/assistantResult'
const questions=['今日有哪些 PPE 违规？','统计最近的安全事件','有哪些未戴安全帽事件？','总结当前安全风险','查看最近的事件明细','查看待处理事件明细'],dates=ref([]),input=ref(''),messages=ref([]),busy=ref(false),service=ref(null),error=ref('')
async function loadService(){try{service.value=await api.capabilities()}catch(e){error.value=errorMessage(e)}}
onMounted(loadService);watch(()=>useUiStore().refreshKey,loadService)
const filters=reactive({event_type:'',status:'',track_id:null})
const chat=ref()
watch(()=>messages.value.length,async()=>{await nextTick();chat.value?.scrollTo({top:chat.value.scrollHeight})})
async function send(question=input.value){if(busy.value||!question.trim())return;const q=question.trim();messages.value.push({role:'user',text:q});input.value='';busy.value=true;try{if(Object.values(filters).some(value=>value!==''&&value!==null)&&!service.value?.assistant_read_tools)throw new Error('当前后端尚未加载事件筛选能力，请重启后端后刷新页面');const p=assistantPayload(q,dates.value);for(const key of ['event_type','status','track_id'])if(filters[key]!==''&&filters[key]!==null)p[key]=filters[key];messages.value[messages.value.length-1].period=p.start_at?`${new Date(p.start_at).toLocaleString('zh-CN')} 至 ${new Date(p.end_at).toLocaleString('zh-CN')}`:'全部已持久化事件';const answer=await api.ask(p);messages.value.push({role:'assistant',...answer})}catch(e){messages.value.push({role:'assistant',text:errorMessage(e),error:true});ElMessage.error(errorMessage(e))}finally{busy.value=false}}
</script><template><section class="assistant-page"><div class="page-head"><div><h1>安全助手</h1><p>基于已持久化事件的只读安全查询</p></div><el-tag type="info">只读模式</el-tag></div><div class="grid-2 assistant-grid"><div class="card assistant-chat-card"><div ref="chat" class="chat"><div v-if="!messages.length" class="empty">请输入关于 PPE 事件的问题，回答会展示实际可用的数据引用。</div><div v-for="(message,i) in messages" :key="i" class="bubble" :class="message.role"><template v-if="message.role==='user'">{{message.text}}<small class="message-period">查询范围：{{message.period}}</small></template><template v-else><p :class="{error:message.error}">{{agentLine(message.answer||message.text)}}</p><div v-if="assistantResult(message).total!==null" class="result-total">查询范围内共 {{assistantResult(message).total}} 条事件</div><div v-if="assistantResult(message).lines.length"><strong>结果与解读</strong><p v-for="(line,j) in assistantResult(message).lines" :key="j">{{line}}</p></div><div v-if="assistantResult(message).events.length" class="assistant-event-list"><strong>事件明细 · 本条回答展示 {{assistantResult(message).events.length}} 条</strong><article v-for="event in assistantResult(message).events" :key="event.id" class="assistant-event"><div><strong>{{event.type}}</strong><el-tag size="small" type="info">{{event.status}}</el-tag></div><p>{{new Date(event.time).toLocaleString('zh-CN')}} · Track ID {{event.track}}</p><small class="muted">模型置信度 {{(event.confidence*100).toFixed(1)}}% · {{event.id}}</small><div><router-link :to="{path:'/events',query:{id:event.id}}">查看事件</router-link> · <router-link :to="{path:'/evidence',query:{id:event.id}}">查看证据与校验</router-link></div></article><small class="muted">展示的是本条回答引用的明细，完整记录及分页请前往事件中心。</small></div><div v-if="message.recommendations?.length"><strong>复核建议</strong><p v-for="(line,j) in message.recommendations" :key="j">{{agentLine(line)}}</p></div><el-collapse v-if="assistantResult(message).references.length" class="assistant-references"><el-collapse-item :title="`数据依据 · ${assistantResult(message).references.length} 个引用（点击展开）`"><p class="muted">引用存在不代表完整性校验通过，可进入证据中心核验。</p><div class="assistant-reference-grid"><div v-for="item in assistantResult(message).references" :key="item.reference"><template v-if="item.id"><el-image :src="`/api/v1/evidence/${encodeURIComponent(item.id)}/image`" :preview-src-list="[`/api/v1/evidence/${encodeURIComponent(item.id)}/image`]" preview-teleported fit="contain" loading="lazy"><template #error><span class="muted">证据不可用或校验未通过</span></template></el-image><router-link :to="{path:'/evidence',query:{id:item.id}}">查看关联证据</router-link></template><span v-else>{{item.reference}}</span></div></div></el-collapse-item></el-collapse><small class="muted">{{agentStatus(message.safe_status)}}</small></template></div><div v-if="busy" class="bubble assistant muted">正在执行受控查询，请稍候…</div></div><div class="composer"><el-input v-model="input" placeholder="询问安全事件、统计或证据…" style="flex:1" maxlength="2000" @keyup.enter="send()"/><el-button type="primary" :loading="busy" :disabled="!input.trim()" @click="send()">发送</el-button></div></div><div class="stack assistant-side"><div class="card"><h2>快捷提问</h2><div class="quick"><button v-for="q in questions" :key="q" :disabled="busy" @click="send(q)">{{q}} →</button></div></div><div class="card"><h2>事件筛选（只读）</h2><div class="stack"><el-select v-model="filters.event_type" clearable placeholder="全部事件类型" :disabled="busy"><el-option v-for="(name,key) in typeName" :key="key" :label="name" :value="key"/></el-select><el-select v-model="filters.status" clearable placeholder="全部处理状态" :disabled="busy"><el-option v-for="(name,key) in statusName" :key="key" :label="name" :value="key"/></el-select><el-input-number v-model="filters.track_id" :min="0" :precision="0" placeholder="Track ID（可选）" :disabled="busy" style="width:100%"/></div></div><div class="card"><h2>日期范围</h2><el-date-picker v-model="dates" :disabled="busy" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" style="max-width:100%"/></div><div class="card"><h2>查询依据与服务状态</h2><p>支持“最近5分钟之内有什么安全事件”等最近 7 天内查询；手动日期范围优先。可读取已保存事件的统计、明细、处理状态和证据引用；也可直接输入事件编号询问详情。Track ID 不代表人员身份。不允许修改状态、删除事件、训练或执行 SQL。</p><p v-if="service">监控能力：{{service.monitoring?'可用':'不可用'}}<br>模型配置：{{service.provider_configured?'已配置':'本地查询/降级'}}</p><el-alert v-if="error" type="error" :title="error" :closable="false"/></div></div></div></section></template>

<style scoped>
.result-total{font-weight:600;margin:12px 0;color:var(--primary-color)}
.assistant-event-list{display:grid;gap:12px;margin:14px 0}
.assistant-event{padding:12px;background:var(--card-background);border:1px solid var(--border-color);border-radius:8px;overflow-wrap:anywhere}
.assistant-event>div:first-child{display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap}
.assistant-event p{margin:8px 0}.assistant-event small{display:block;margin-bottom:8px}
.assistant-references{margin:14px 0;background:transparent;--el-collapse-content-bg-color:transparent;--el-collapse-header-bg-color:transparent}
.assistant-reference-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,160px),1fr));gap:12px;overflow-wrap:anywhere}
.assistant-reference-grid .el-image{width:100%;height:110px;display:block;margin-bottom:8px}
</style>
